import { useState, useEffect } from 'react';
import axios from '../../api/axiosInstance';
import { useLocation, useNavigate } from 'react-router-dom';

const AddProject = () => {
    const location = useLocation();
    const navigate = useNavigate();
    const editData = location.state?.editData || null;

    const [form, setForm] = useState({
        name: '', description: '', startDate: '', endDate: '',
        budget: '', progress: '', image: null
    });

    useEffect(() => {
        if (editData) {
            setForm({
                name: editData.name,
                description: editData.description,
                startDate: editData.startDate?.slice(0, 10),
                endDate: editData.endDate?.slice(0, 10),
                budget: editData.budget,
                progress: editData.progress,
                image: null
            });
        }
    }, [editData]);

    const handleSubmit = async (e) => {
        e.preventDefault();
        const formData = new FormData();
        Object.keys(form).forEach(key => {
            if (form[key]) formData.append(key, form[key]);
        });

        if (editData) {
            await axios.put(`/projects/${editData._id}`, formData);
            alert('Cập nhật dự án thành công');
        } else {
            await axios.post('/projects', formData);
            alert('Thêm dự án thành công');
        }

        setForm({ name: '', description: '', startDate: '', endDate: '', budget: '', progress: '', image: null });
        navigate('/admin/projects/list');
    };

    return (
        <div>
            <h2>{editData ? '🛠️ Cập nhật Dự án' : '➕ Thêm Dự án'}</h2>
            <form onSubmit={handleSubmit} encType="multipart/form-data">
                <input type="text" placeholder="Tên dự án" value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} required /><br />
                <textarea placeholder="Mô tả" value={form.description} onChange={e => setForm({ ...form, description: e.target.value })}></textarea><br />
                <input type="number" placeholder="Ngân sách" value={form.budget} onChange={e => setForm({ ...form, budget: e.target.value })} /><br />
                <input type="number" placeholder="Tiến độ (%)" value={form.progress} onChange={e => setForm({ ...form, progress: e.target.value })} /><br />
                <input type="date" value={form.startDate} onChange={e => setForm({ ...form, startDate: e.target.value })} />
                <input type="date" value={form.endDate} onChange={e => setForm({ ...form, endDate: e.target.value })} /><br />
                <input type="file" accept="image/*" onChange={e => setForm({ ...form, image: e.target.files[0] })} /><br /><br />
                <button type="submit">{editData ? '💾 Lưu cập nhật' : '➕ Thêm Dự án'}</button>
            </form>
        </div>
    );
};

export default AddProject;
